<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {renderArticle} from './articleMarkdown.js';
const emit=defineEmits(['profile-saved']);
const route=useRoute(),router=useRouter();
const me=ref(null),data=ref(null),form=ref({}),tax=ref({categories:[],tags:[]}),choices=ref([]),expected=ref([]),baseline=ref(''),csrf=ref(''),error=ref(''),message=ref(''),loading=ref(true),busy=ref(false);
const labels={DRAFT:'草稿',PENDING:'待审核',PUBLISHED:'已发布',REJECTED:'已驳回',OFFLINE:'已下架'};
const mode=computed(()=>route.path.startsWith('/series/')?'public':route.path==='/me/profile'?'profile':route.path==='/studio'?'overview':route.path==='/studio/series'?'seriesList':route.path.startsWith('/studio/series/')?'seriesEdit':'article');
const dirty=computed(()=>baseline.value!==''&&JSON.stringify(form.value)!==baseline.value);
const editable=computed(()=>['DRAFT','REJECTED'].includes(form.value.status));
const preview=computed(()=>renderArticle(form.value.bodyMarkdown||'').html);
const timeline=computed(()=>route.query.view==='timeline');
const publicArticles=computed(()=>timeline.value?[...(data.value?.articles||[])].sort((a,b)=>new Date(a.firstPublishedAt)-new Date(b.firstPublishedAt)||(BigInt(a.id)<BigInt(b.id)?-1:1)):data.value?.articles||[]);
function markSaved(){baseline.value=JSON.stringify(form.value);}
const confirmDialog=ref(null),confirmText=ref('');let resolveConfirm;
async function ask(text){if(resolveConfirm)return false;confirmText.value=text;await nextTick();confirmDialog.value.showModal();return new Promise(resolve=>{resolveConfirm=resolve;});}
function answer(value){confirmDialog.value.close();const done=resolveConfirm;resolveConfirm=null;done?.(value);}
function leave(){return !dirty.value||ask('有尚未保存的修改，确定离开吗？');}
onBeforeRouteLeave(()=>leave());onBeforeRouteUpdate((to,from)=>to.path===from.path||leave());
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onUnmounted(()=>{generation++;window.removeEventListener('beforeunload',beforeUnload);});
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:method==='GET'?{}:{'X-CSRF-Token':csrf.value,...(body instanceof FormData?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:body instanceof FormData?body:JSON.stringify(body)})});const j=await r.json();if(!r.ok){if(r.status===401)router.push({path:'/login',query:{next:route.fullPath}});throw new Error(j.message||'请求失败');}return j.data;}
let generation=0;
async function load(){const g=++generation;loading.value=true;error.value='';baseline.value='';try{
  csrf.value=(await api('/auth/csrf')).token;const current=await api('/auth/me');if(g!==generation)return;me.value=current;
  if(mode.value!=='public'&&current?.role!=='USER'){if(!current)router.replace({path:'/login',query:{next:route.fullPath}});else error.value='创作功能仅供普通用户使用';return;}
  let result,fields={},options=[];
  if(mode.value==='public')result=await api('/series/'+route.params.id);
  if(mode.value==='overview'){const [counts,list]=await Promise.all([api('/studio/overview'),api('/studio/articles?'+new URLSearchParams(route.query))]);result={counts,...list};}
  if(mode.value==='seriesList')result=await api('/studio/series');
  if(mode.value==='profile')fields={nickname:current.nickname,bio:current.bio||'',avatarPath:current.avatarPath||null};
  if(mode.value==='article'){tax.value=await api('/taxonomy');fields=route.params.id?await api('/studio/articles/'+route.params.id):{title:'',summary:'',bodyMarkdown:'',categoryId:null,tagIds:[],coverPath:null,status:'DRAFT',version:1};result=fields;}
  if(mode.value==='seriesEdit'){fields=await api('/studio/series/'+route.params.id);result=fields;let page=1;do{const r=await api('/studio/articles?page='+page+'&pageSize=50');options.push(...r.items);if(page*50>=r.total)break;page++;}while(page<=10000);}
  if(g!==generation)return;data.value=result;form.value=structuredClone(fields);choices.value=options;expected.value=(fields.articles||[]).map(a=>a.id);markSaved();
}catch(e){if(g===generation)error.value=e.message;}finally{if(g===generation)loading.value=false;}}
watch(()=>route.fullPath,()=>{message.value='';load();},{immediate:true});
async function act(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function saveArticle(){let result;if(form.value.id){result=await api('/studio/articles/'+form.value.id,'PATCH',form.value);Object.assign(form.value,result);markSaved();}else{result=await api('/studio/articles','POST',form.value);markSaved();await router.replace('/studio/articles/'+result.id+'/edit');}message.value='已保存 · '+new Date().toLocaleTimeString('zh-CN');}
async function transition(action){if(dirty.value){error.value='请先保存修改，再执行状态操作';return;}if(['withdraw','delete'].includes(action)&&!await ask(action==='delete'?'确定删除这篇文章？':'确定撤回文章？已发布文章将停止公开。'))return;const f=form.value;await api('/studio/articles/'+f.id+(action==='delete'?'':'/'+action),action==='delete'?'DELETE':'POST',{version:f.version});if(action==='delete'){baseline.value='';await router.push('/studio');}else await load();}
async function upload(event,key){const file=event.target.files?.[0];if(!file)return;await act(async()=>{const body=new FormData();body.append('image',file);form.value[key]=(await api('/uploads/images','POST',body)).path;});event.target.value='';}
async function saveSeries(){await api('/studio/series/'+form.value.id+'/articles','PUT',{...form.value,expectedIds:expected.value});markSaved();await load();message.value='专栏已保存';}
function move(index,delta){const a=form.value.articles;if(index+delta<0||index+delta>=a.length)return;[a[index],a[index+delta]]=[a[index+delta],a[index]];}
function addArticle(event){const item=choices.value.find(a=>a.id===event.target.value);if(item&&!form.value.articles.some(a=>a.id===item.id))form.value.articles.push({id:item.id,title:item.title,status:item.status,stage:null});event.target.value='';}
const date=value=>value?new Date(value).toLocaleString('zh-CN'):'—';
</script>

<template>
<section class="creator-panel" :aria-busy="busy||loading"><dialog ref="confirmDialog" class="creator-confirm" aria-labelledby="creator-confirm-title" @cancel.prevent="answer(false)"><h2 id="creator-confirm-title">确认操作</h2><p>{{confirmText}}</p><div class="creator-actions"><button autofocus @click="answer(false)">取消</button><button class="primary" @click="answer(true)">确定</button></div></dialog>
  <header class="creator-heading"><RouterLink :to="mode==='public'?'/':'/studio'">{{mode==='public'?'首页':'创作中心'}}</RouterLink><nav v-if="mode!=='public'" aria-label="创作导航"><RouterLink to="/studio/articles/new">写文章</RouterLink><RouterLink to="/studio/series">专栏</RouterLink><RouterLink to="/me/profile">资料</RouterLink></nav></header>
  <p v-if="error" role="alert" class="notice">{{error}} <button :disabled="busy" @click="async()=>{if(await leave())load();}">重新加载</button></p><p v-if="message" role="status">{{message}}</p>
  <div v-if="loading" class="page-skeleton" aria-label="加载中"><div class="skeleton-line"/><div class="skeleton-line"/></div>
  <template v-else-if="mode==='overview'&&data">
    <h1>我的创作</h1><div class="creator-counts"><span v-for="(n,state) in data.counts" :key="state">{{labels[state]}} {{n}}</span></div>
    <label>文章状态<select :value="route.query.status||''" @change="router.push({query:{status:$event.target.value,page:1}})"><option value="">全部</option><option v-for="(label,state) in labels" :value="state" :key="state">{{label}}</option></select></label>
    <article v-for="a in data.items" :key="a.id" class="creator-row"><RouterLink :to="'/studio/articles/'+a.id+'/edit'"><strong>{{a.title||'未命名草稿'}}</strong></RouterLink><p>{{labels[a.status]}} · {{date(a.updatedAt)}}</p></article><p v-if="!data.items.length">还没有此状态的文章。</p>
    <nav class="pagination" aria-label="创作分页"><button :disabled="data.page<=1" @click="router.push({query:{...route.query,page:data.page-1}})">上一页</button><span>第 {{data.page}} 页</span><button :disabled="data.page*data.pageSize>=data.total" @click="router.push({query:{...route.query,page:data.page+1}})">下一页</button></nav>
  </template>
  <template v-else-if="mode==='article'&&form.status">
    <h1>{{form.id?'文章管理':'新建文章'}}</h1><p>{{labels[form.status]}} <span v-if="form.updatedAt">· 保存于 {{date(form.updatedAt)}}</span> <span v-if="dirty">· 尚未保存</span></p>
    <form @submit.prevent="act(saveArticle)"><fieldset :disabled="busy||!editable"><label>标题<input v-model="form.title" maxlength="80"></label><label>摘要<textarea v-model="form.summary" maxlength="200" rows="3"/></label><label>分类<select v-model="form.categoryId"><option :value="null">请选择</option><option v-for="c in tax.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label>
    <fieldset><legend>标签（最多5个）</legend><label v-for="tag in tax.tags" :key="tag.id" class="creator-check"><input v-model="form.tagIds" type="checkbox" :value="tag.id">{{tag.name}}</label></fieldset>
    <label>封面<input type="file" accept="image/jpeg,image/png,image/webp" @change="upload($event,'coverPath')"></label><img v-if="form.coverPath" :src="form.coverPath" alt="文章封面" class="creator-cover"><button v-if="form.coverPath" type="button" @click="form.coverPath=null">移除封面</button>
    <label>Markdown 正文<textarea v-model="form.bodyMarkdown" rows="18" maxlength="50000" class="creator-editor"/></label><details><summary>正文预览</summary><div class="article-body" v-html="preview"/></details><button type="submit" class="primary">{{busy?'处理中…':'保存草稿'}}</button></fieldset></form>
    <div class="creator-actions"><button v-if="form.id&&editable" :disabled="busy||dirty" @click="act(()=>transition('submit'))">提交审核</button><button v-if="['PENDING','PUBLISHED'].includes(form.status)" :disabled="busy" @click="act(()=>transition('withdraw'))">撤回为草稿</button><button v-if="form.status==='OFFLINE'" :disabled="busy" @click="act(()=>transition('revise'))">整改为草稿</button><button v-if="form.id&&['DRAFT','REJECTED','OFFLINE'].includes(form.status)" :disabled="busy" @click="act(()=>transition('delete'))">删除文章</button></div>
    <section v-if="form.history?.length"><h2>审核记录</h2><article v-for="(h,i) in form.history" :key="i" class="creator-row"><p>{{labels[h.toStatus]}} · {{date(h.createdAt)}}</p><p>{{h.reason||'审核通过'}}</p></article></section>
  </template>
  <template v-else-if="mode==='seriesList'&&data"><h1>我的成长专栏</h1><button :disabled="busy" @click="act(async()=>{const s=await api('/studio/series','POST',{name:'新专栏',description:'',isPublic:false});router.push('/studio/series/'+s.id);})">新建专栏</button><article v-for="s in data" :key="s.id" class="creator-row"><RouterLink :to="'/studio/series/'+s.id">{{s.name}}</RouterLink><p>{{s.isPublic?'公开':'隐藏'}}</p></article><p v-if="!data.length">还没有专栏。</p></template>
  <template v-else-if="mode==='seriesEdit'&&form.id"><h1>管理专栏</h1><form @submit.prevent="act(saveSeries)"><fieldset :disabled="busy"><label>名称<input v-model="form.name" minlength="2" maxlength="40" required></label><label>简介<textarea v-model="form.description" maxlength="300"/></label><label class="creator-check"><input v-model="form.isPublic" type="checkbox">公开专栏</label><label>专栏封面<input type="file" accept="image/jpeg,image/png,image/webp" @change="upload($event,'coverPath')"></label><img v-if="form.coverPath" :src="form.coverPath" class="creator-cover" alt="专栏封面"><button v-if="form.coverPath" type="button" @click="form.coverPath=null">移除封面</button>
    <label>添加文章<select :disabled="form.articles.length>=50" @change="addArticle"><option value="">选择本人文章</option><option v-for="a in choices.filter(a=>!form.articles.some(x=>x.id===a.id))" :key="a.id" :value="a.id">{{a.title||'未命名草稿'}} · {{labels[a.status]}}</option></select></label>
    <article v-for="(a,i) in form.articles" :key="a.id" class="creator-row"><strong>{{a.title||'未命名草稿'}}</strong><p>{{labels[a.status]}}</p><label>成长阶段<select v-model="a.stage"><option :value="null">未设置</option><option v-for="s in ['起步','实践','成果','复盘']" :key="s">{{s}}</option></select></label><div class="creator-actions"><button type="button" :disabled="i===0" @click="move(i,-1)" :aria-label="'上移'+a.title">上移</button><button type="button" :disabled="i===form.articles.length-1" @click="move(i,1)" :aria-label="'下移'+a.title">下移</button><button type="button" @click="form.articles.splice(i,1)">移出专栏</button></div></article><button type="submit" class="primary">保存专栏</button></fieldset></form><div class="creator-actions"><RouterLink :to="'/series/'+form.id">查看公开页</RouterLink><button :disabled="busy" @click="act(async()=>{if(!await ask('删除专栏将解除文章关联，文章仍保留。确定删除？'))return;await api('/studio/series/'+form.id,'DELETE');baseline='';router.push('/studio/series');})">删除专栏</button></div></template>
  <template v-else-if="mode==='public'&&data"><img v-if="data.coverPath" :src="data.coverPath" alt="专栏封面" class="creator-cover"><h1>{{data.name}}</h1><RouterLink :to="'/users/'+data.authorId">{{data.author}}</RouterLink><p>{{data.description}}</p><p>{{data.count}} 篇公开文章 · 更新于 {{date(data.updatedAt)}}</p><nav class="creator-actions" aria-label="专栏视图"><RouterLink :to="{query:{}}" :aria-current="!timeline?'page':undefined">章节目录</RouterLink><RouterLink :to="{query:{view:'timeline'}}" :aria-current="timeline?'page':undefined">成长时间线</RouterLink></nav><article v-for="(a,i) in publicArticles" :key="a.id" class="creator-row"><p>{{timeline?date(a.firstPublishedAt):'第 '+(i+1)+' 章'}} <span v-if="a.stage">· {{a.stage}}</span></p><RouterLink :to="'/articles/'+a.id"><h2>{{a.title}}</h2></RouterLink><p>{{a.summary}}</p></article></template>
  <template v-else-if="mode==='profile'&&me?.role==='USER'"><h1>编辑个人资料</h1><form @submit.prevent="act(async()=>{const profile=await api('/me/profile','PATCH',form);me={...me,...profile};markSaved();emit('profile-saved',profile);message='个人资料已保存';})"><fieldset :disabled="busy"><label>昵称<input v-model="form.nickname" minlength="2" maxlength="30" required></label><label>简介<textarea v-model="form.bio" maxlength="300" rows="4"/></label><label>头像<input type="file" accept="image/jpeg,image/png,image/webp" @change="upload($event,'avatarPath')"></label><img v-if="form.avatarPath" :src="form.avatarPath" class="creator-avatar" alt="当前头像"><button v-if="form.avatarPath" type="button" @click="form.avatarPath=null">移除头像</button><button type="submit" class="primary">保存资料</button></fieldset></form></template>
</section>
</template>

<style scoped>
.creator-confirm{max-width:min(420px,85vw);border:1px solid #E8ECE8;border-radius:12px;padding:24px}.creator-confirm::backdrop{background:rgb(32 39 34 / 35%)}.creator-panel{padding:24px;overflow-wrap:anywhere}.creator-heading,.creator-heading nav,.creator-actions,.creator-counts{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.creator-heading{justify-content:space-between;padding-bottom:20px;border-bottom:1px solid #E8ECE8}.creator-panel h1{font-size:22px;margin:24px 0 16px}.creator-panel h2{font-size:19px}.creator-panel fieldset{border:0;padding:0;margin:16px 0;min-width:0}.creator-panel label{display:block;margin:16px 0 8px}.creator-panel input:not([type=checkbox]),.creator-panel textarea,.creator-panel select{display:block;width:100%;box-sizing:border-box;margin-top:8px;min-height:44px}.creator-panel .creator-check input{width:18px;height:18px;min-height:18px;margin:0;flex-shrink:0}.creator-panel .creator-check{white-space:nowrap;min-height:44px;display:inline-flex;gap:8px;align-items:center;margin-right:12px}.creator-editor{font-family:monospace;line-height:1.7}.creator-actions{margin:18px 0}.creator-row{padding:20px 0;border-bottom:1px solid #E8ECE8}.creator-row p{color:#627166}.creator-cover{max-width:100%;max-height:280px;object-fit:contain}.creator-panel fieldset>button{margin:8px 8px 8px 0}.creator-avatar{display:block;margin:12px 0;width:88px;height:88px;object-fit:cover;border-radius:50%}.creator-panel button{min-height:44px}.creator-panel button:disabled{opacity:.55;cursor:default}.creator-panel details{margin:20px 0}.creator-panel summary{cursor:pointer;min-height:44px}.creator-panel a[aria-current=page]{font-weight:700;text-decoration:underline}.creator-panel :focus-visible{outline:2px solid #315C52;outline-offset:3px}@media(max-width:720px){.creator-panel{padding:18px}.creator-heading nav{gap:10px}}
</style>
